arguments.code:
const queries = ["Vercel project environment variables list", "Vercel deployment protection bypass create revoke list", "Vercel production deployment project logs", "Sendblue webhook list create receive", "Sendblue messages list send", "Vercel project deployment list"];
const results = await Promise.all(queries.map(async (query) => {
  const found = await tools.search({ query, limit: 8 });
  return { query, items: found.items.map((item) => ({ path: item.path, description: item.description })) };
}));
return results;

