const searches = await Promise.all([
  tools.search({ namespace: "sendblue_api", query: "webhook", limit: 50 }),
  tools.search({ namespace: "vercel_api", query: "bypass protection", limit: 50 }),
  tools.search({ namespace: "vercel_api", query: "deployment bypass", limit: 50 }),
  tools.search({ namespace: "vercel_api", query: "list deployments", limit: 50 })
]);
return searches.map((result) => result.items.map((item) => ({ path: item.path, description: item.description })));

